def orchestrate_interaction(customer, channel_event_stream):
    # 1. Do not build a monolithic decision engine; walled gardens and latency make it impossible.
    # Maintain a real-time 'attention shadow price' per customer rather than dictating exact content.
    shadow_price = compute_fatigue_and_urgency_cost(customer.recent_touches, customer.open_support_cases)

    # 2. Let decentralized channel systems generate proposals within their native execution environments
    proposals = []
    for channel in get_active_channels(customer):
        # Channels calculate local expected value under their own constraints and timing
        candidate = channel.evaluate_best_candidate(customer.profile_snapshot)
        # Deduct global attention cost; forces high-volume batch channels (email/push) to compete fairly with ads/web
        net_score = candidate.projected_incremental_ltv - shadow_price[candidate.channel_type] - candidate.direct_cost
        if net_score > 0:
            proposals.append((net_score, candidate))

    # 3. Hard safety: immediate service intent or unresolved friction trumps all marketing bids
    if customer.has_unresolved_complaint:
        return execute_suppression_and_service_routing(proposals)

    # 4. Stochastic winner selection to deliberately gather counterfactual loss data across channels
    selected_action = epsilon_greedy_arbitrate(proposals, fallback=DO_NOTHING)
    emit_shadow_telemetry(customer.id, selected_action, unselected=proposals)
    return dispatch(selected_action)
